def filter_primes(numbers):
    """
    Return a new list containing only the prime numbers from the input list.

    Parameters:
        numbers (list of int): The input array of integers.

    Returns:
        list of int: A new list containing only the prime numbers.
    """
    def is_prime(n):
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(n**0.5) + 1, 2):
            if n % i == 0:
                return False
        return True

    return [x for x in numbers if is_prime(x)]
