def max_area(heights):
    """
    Returns the maximum area of a rectangle formed by buildings.
    The width between buildings i and j is j - i.
    The height of the rectangle is the minimum of the heights at i and j.
    """
    if not heights:
        return 0

    n = len(heights)
    if n < 2:
        return 0

    left = [0] * n
    right = [0] * n

    # Fill left array: left[i] = index of the first building to the left of i with height >= heights[i]
    for i in range(n):
        for j in range(i, n):
            if heights[j] >= heights[i]:
                left[i] = j

    # Fill right array: right[i] = index of the first building to the right of i with height >= heights[i]
    for i in range(n - 1, -1, -1):
        for j in range(i, n):
            if heights[j] >= heights[i]:
                right[i] = j

    max_area = 0

    for i in range(n):
        h = heights[i]
        area = 0
        # Left boundary: first index to the left with height >= h
        j = left[i]
        while j > 0 and heights[j - 1] >= h:
            j -= 1
        # Right boundary: first index to the right with height >= h
        k = right[i]
        while k < n and heights[k + 1] >= h:
            k += 1
        area = (k - j) * h
        max_area = max(max_area, area)

    return max_area
