def remove_duplicates(s: str) -> str:
    """
    Return a new string t such that:
    - Each character from s appears in t exactly once in the same order as in s.
    - If a character appears multiple times in s, only the first occurrence is kept.
    - Return "" for an empty string.
    """
    if not s:
        return ""

    # Use a dictionary to store the first occurrence of each character
    first_occurrence = {}
    for char in s:
        if char not in first_occurrence:
            first_occurrence[char] = char

    # Build the result string by iterating through the first occurrences
    result = []
    for char in first_occurrence:
        result.append(char)

    return "".join(result)
